#include <bits/stdc++.h>using namespace std; int main() {    ios::sync_with_stdio(false);    cin.tie(NULL);     int t;    cin >> t;     while (t--) {        int n, m;        cin >> n >> m;         int negCount = 0;        int minAbs = INT_MAX;        int sum = 0;         for (int i = 0; i < n; i++) {            for (int j = 0; j < m; j++) {                int x;                cin >> x;                 if (x < 0) negCount++;                 sum += abs(x);                minAbs = min(minAbs, abs(x));            }        }         // If negatives are odd → one must remain negative        if (negCount % 2 == 1) {            sum -= 2 * minAbs;        }         cout << sum << "\n";    }     return 0;}